  document.getElementById('mCompanyViewArea').innerHTML   = _renderCompanyView(ci);
  document.getElementById('mCompanyFormArea').innerHTML   = _renderCompanyForm(ci);
  document.getElementById('mCompanyViewArea').style.display  = '';
